"use client";

/**
 * GlbPrefabMesh — loads a .glb file and renders it as a draggable prefab.
 *
 * "Transformer decomposition" model:
 *   Each part of the villa (pool, pergola, gate, car shelter…) is a
 *   *separate* GLB generated by TripoSR / SF3D and loaded here as its
 *   own independent scene node.  Parts are individually positionable,
 *   scalable, and colourable — exactly like Transformer toy joints.
 *
 * Material override system:
 *   traverse() walks the mesh tree and replaces each mesh's color while
 *   keeping the original roughness / normal map / metalness so the
 *   lighting still looks correct. Pass `partColor` to override.
 *
 * Usage inside PrefabRenderer:
 *   <GlbPrefabMesh src="/models/generated/pool.glb" color="#00B4D8" scale={1} />
 */

import { Suspense, useEffect, useMemo } from "react";
import { useGLTF, Html } from "@react-three/drei";
import * as THREE from "three";

// ─── Colour applicator ────────────────────────────────────────────
// Walks the cloned scene tree and overrides colour on every Mesh whose
// material is MeshStandardMaterial (covers 99 % of TripoSR / SF3D output).
// We clone() each material so we don't mutate shared instances.
function applyColorOverride(root: THREE.Object3D, hexColor: string) {
  const color = new THREE.Color(hexColor);
  root.traverse((child) => {
    if (!(child instanceof THREE.Mesh)) return;
    const mats = Array.isArray(child.material) ? child.material : [child.material];
    child.material = mats.map((m) => {
      if (!(m instanceof THREE.MeshStandardMaterial)) return m;
      const clone = m.clone();
      clone.color = color;
      return clone;
    });
    if (!Array.isArray(child.material) && child.material.length === 1) {
      child.material = child.material[0];
    }
  });
}

// ─── Part-level material override ─────────────────────────────────
// For GLBs exported from Blender with named nodes (e.g. "Roof", "Pool_Water"),
// you can override individual nodes by passing a map.
function applyNodeOverrides(
  root: THREE.Object3D,
  overrides: Record<string, string>, // nodeName → hexColor
) {
  root.traverse((child) => {
    if (!(child instanceof THREE.Mesh)) return;
    const hex = overrides[child.name];
    if (!hex) return;
    const m = Array.isArray(child.material) ? child.material[0] : child.material;
    if (m instanceof THREE.MeshStandardMaterial) {
      const clone = m.clone();
      clone.color = new THREE.Color(hex);
      child.material = clone;
    }
  });
}

// ─── Inner loader (inside Suspense) ──────────────────────────────
function GlbInner({
  src,
  partColor,
  nodeOverrides,
  castShadow,
}: {
  src: string;
  partColor?: string;
  nodeOverrides?: Record<string, string>;
  castShadow?: boolean;
}) {
  const { scene } = useGLTF(src);

  // Clone the scene so multiple instances don't share materials
  const cloned = useMemo(() => {
    const c = scene.clone(true);
    // Enable shadows on every mesh
    c.traverse((child) => {
      if (child instanceof THREE.Mesh) {
        child.castShadow    = castShadow ?? true;
        child.receiveShadow = true;
      }
    });
    return c;
  }, [scene, castShadow]);

  // Apply colour overrides after clone — runs whenever colour props change
  useEffect(() => {
    if (partColor) applyColorOverride(cloned, partColor);
    if (nodeOverrides && Object.keys(nodeOverrides).length > 0) {
      applyNodeOverrides(cloned, nodeOverrides);
    }
  }, [cloned, partColor, nodeOverrides]);

  return <primitive object={cloned} />;
}

// ─── Loading fallback ─────────────────────────────────────────────
function GlbLoadingBox() {
  return (
    <group>
      {/* Transparent bounding-box placeholder while GLB loads */}
      <mesh>
        <boxGeometry args={[1.5, 1.5, 1.5]} />
        <meshStandardMaterial
          color="#6699FF"
          transparent
          opacity={0.18}
          wireframe
        />
      </mesh>
      <Html center style={{ pointerEvents: "none" }}>
        <div style={{
          background: "rgba(0,0,0,0.55)",
          color: "#fff",
          padding: "4px 10px",
          borderRadius: 6,
          fontSize: 11,
          whiteSpace: "nowrap",
        }}>
          ⟳ 加载模型…
        </div>
      </Html>
    </group>
  );
}

// ─── Public component ─────────────────────────────────────────────
export interface GlbPrefabMeshProps {
  /** Path to .glb relative to /public, OR a data: base64 URL */
  src: string;
  /** Hex colour applied to all meshes. Undefined = keep original baked materials. */
  partColor?: string;
  /**
   * Per-node colour overrides.  The key is the Blender mesh name (preserved
   * in the exported GLB node tree).
   * Example: { "Roof_Mesh": "#8B6347", "Pool_Water": "#00B4D8" }
   */
  nodeOverrides?: Record<string, string>;
  castShadow?: boolean;
}

export function GlbPrefabMesh({
  src,
  partColor,
  nodeOverrides,
  castShadow = true,
}: GlbPrefabMeshProps) {
  return (
    <Suspense fallback={<GlbLoadingBox />}>
      <GlbInner
        src={src}
        partColor={partColor}
        nodeOverrides={nodeOverrides}
        castShadow={castShadow}
      />
    </Suspense>
  );
}

// Pre-warm the GLTF cache for a list of model URLs so they load instantly
// when the user drags them into the scene.
export function preloadGlbModels(urls: string[]) {
  for (const url of urls) {
    useGLTF.preload(url);
  }
}
